{
  "type": "sim",
  "engine": "widget",
  "caption": "点击按钮切换优化方法，观察迭代路径与损失曲线",
  "html": "<style>canvas{display:block;margin:0 auto;border:1px solid var(--line);border-radius:8px;background:var(--bg)}.controls{display:flex;gap:8px;justify-content:center;margin-top:8px;flex-wrap:wrap}.controls button{padding:6px 14px;border:1px solid var(--line);border-radius:6px;background:var(--bg);color:var(--ink);cursor:pointer;font-size:14px;transition:background .2s}.controls button.active{background:var(--accent);color:var(--bg);border-color:var(--accent)}.controls button:hover{background:var(--line);color:var(--bg)}.legend{display:flex;gap:16px;justify-content:center;margin-top:6px;font-size:13px;color:var(--ink)}.legend span{display:flex;align-items:center;gap:4px}.legend span::before{content:'';display:inline-block;width:12px;height:3px;border-radius:2px}</style><div class='controls'><button id='btnBGD' class='active'>全批量 BGD</button><button id='btnSGD'>随机 SGD</button><button id='btnMomentum'>动量 Momentum</button></div><div class='legend'><span style='--c:var(--accent)'>路径</span><span style='--c:var(--line)'>损失曲线</span></div><canvas id='cv' width='700' height='400'></canvas><script>(function(){const cv=document.getElementById('cv'),ctx=cv.getContext('2d');const W=700,H=400;const pad={top:30,bottom:40,left:60,right:30};const plotW=W-pad.left-pad.right,plotH=H-pad.top-pad.bottom;const xMin=-2.5,xMax=2.5;const yMin=-1.5,yMax=3.5;const lossH=80;const lossY0=H-pad.bottom-lossH;const lossPlotH=lossH-10;const lossPad=10;const lossW=plotW;const lossX0=pad.left;const f=x=>Math.sin(1.5*x)+0.3*x*x+0.1*x;const df=x=>1.5*Math.cos(1.5*x)+0.6*x+0.1;const x0=-2.0;const steps=50;const lr=0.15;const momentum=0.9;const noiseStd=0.4;let method='BGD';let path=[],losses=[];let animId=null;function run(m){method=m;path=[];losses=[];let x=x0;for(let i=0;i<steps;i++){let g;if(m==='BGD'){g=df(x);}else if(m==='SGD'){g=df(x)+noiseStd*(Math.random()-0.5)*2;}else{//Momentum with BGD gradient for simplicitylet v=0;for(let j=0;j<=i;j++){let g2=df(x);v=momentum*v+lr*g2;x-=v;path.push({x:x,step:j});losses.push(f(x));continue;}break;}x-=lr*g;path.push({x:x,step:i});losses.push(f(x));}}function draw(){ctx.clearRect(0,0,W,H);const ink=getComputedStyle(document.documentElement).getPropertyValue('--ink').trim()||'#333';const accent=getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()||'#007aff';const line=getComputedStyle(document.documentElement).getPropertyValue('--line').trim()||'#ccc';const bg=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim()||'#fff';ctx.strokeStyle=line;ctx.lineWidth=1;ctx.font='12px sans-serif';ctx.fillStyle=ink;//draw function curveconst xs=[];for(let i=0;i<=200;i++){xs.push(xMin+(xMax-xMin)*i/200);}ctx.beginPath();for(let i=0;i<xs.length;i++){const px=pad.left+(xs[i]-xMin)/(xMax-xMin)*plotW;const py=pad.top+plotH-(f(xs[i])-yMin)/(yMax-yMin)*plotH;if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);}ctx.strokeStyle=ink;ctx.lineWidth=2;ctx.globalAlpha=0.3;ctx.stroke();ctx.globalAlpha=1;//axesctx.beginPath();ctx.moveTo(pad.left,pad.top);ctx.lineTo(pad.left,pad.top+plotH);ctx.lineTo(pad.left+plotW,pad.top+plotH);ctx.strokeStyle=line;ctx.lineWidth=1;ctx.stroke();//x axis labelsfor(let i=0;i<=4;i++){const x=xMin+(xMax-xMin)*i/4;const px=pad.left+(x-xMin)/(xMax-xMin)*plotW;ctx.fillText(x.toFixed(1),px-10,pad.top+plotH+16);}//y axis labelsfor(let i=0;i<=5;i++){const y=yMin+(yMax-yMin)*i/5;const py=pad.top+plotH-(y-yMin)/(yMax-yMin)*plotH;ctx.fillText(y.toFixed(1),pad.left-35,py+4);}//draw pathif(path.length>0){ctx.beginPath();for(let i=0;i<path.length;i++){const px=pad.left+(path[i].x-xMin)/(xMax-xMin)*plotW;const py=pad.top+plotH-(f(path[i].x)-yMin)/(yMax-yMin)*plotH;if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);}ctx.strokeStyle=accent;ctx.lineWidth=2.5;ctx.stroke();//pointsfor(let i=0;i<path.length;i++){const px=pad.left+(path[i].x-xMin)/(xMax-xMin)*plotW;const py=pad.top+plotH-(f(path[i].x)-yMin)/(yMax-yMin)*plotH;ctx.beginPath();ctx.arc(px,py,3,0,2*Math.PI);ctx.fillStyle=accent;ctx.fill();}}//draw loss curveif(losses.length>0){const maxLoss=Math.max(...losses);const minLoss=Math.min(...losses);const range=maxLoss-minLoss||1;ctx.beginPath();for(let i=0;i<losses.length;i++){const px=lossX0+(i/(losses.length-1||1))*lossW;const py=lossY0+lossPlotH-(losses[i]-minLoss)/range*lossPlotH;if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);}ctx.strokeStyle=line;ctx.lineWidth=2;ctx.stroke();//loss axis labelsctx.fillStyle=ink;ctx.font='10px sans-serif';ctx.fillText('损失',lossX0-30,lossY0+lossPlotH/2+4);ctx.fillText('0',lossX0-15,lossY0+lossPlotH+4);ctx.fillText(maxLoss.toFixed(2),lossX0-30,lossY0+4);}requestAnimationFrame(draw);}function setMethod(m){document.querySelectorAll('.controls button').forEach(b=>b.classList.remove('active'));document.getElementById('btn'+m).classList.add('active');run(m);draw();}document.getElementById('btnBGD').addEventListener('click',()=>setMethod('BGD'));document.getElementById('btnSGD').addEventListener('click',()=>setMethod('SGD'));document.getElementById('btnMomentum').addEventListener('click',()=>setMethod('Momentum'));run('BGD');draw();})();</script>"
}
